# --------------------------------------------------------------------------- host side


def _file_sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _pinned_triples(constraints: Any) -> list[tuple[list, dict, dict | None]]:
    """(args, kwargs, expected) per pinned input; expected is the recorded base outcome or None."""
    out: list[tuple[list, dict, dict | None]] = []
    for p in getattr(constraints, "pinned_inputs", ()) or ():
        if hasattr(p, "args") or hasattr(p, "kwargs"):
            a, k, e = getattr(p, "args", []), getattr(p, "kwargs", {}), getattr(p, "expected", None)
        else:
            a, k, e = (*p, None)[:3]
        out.append((list(a or []), dict(k or {}), dict(e) if e else None))
    return out


def _pinned_envs(constraints: Any) -> list[dict | None]:
    """Optional per-pin environment (review: Pinned.env), aligned with _pinned_triples."""
    out = []
    for p in getattr(constraints, "pinned_inputs", ()) or ():
        e = getattr(p, "env", None)
        out.append({str(k): (None if v is None else str(v)) for k, v in e.items()} if isinstance(e, dict) else None)
    return out


_BYTES_TAG = "__hlith_bytes__"
_BYTES_HEX_MAX = 64 * 1024  # hex characters (32 KiB of bytes): a seed is a probe, not a payload channel


def _bytes_tag_problem(v: Any, depth: int = 0) -> str | None:
    """Validate every {"__hlith_bytes__": "<hex>"} node of an external seed value (top level, nested in list / dict /
    {"__hlith_tuple__": [...]}): even-length hex of at most _BYTES_HEX_MAX characters, nothing else in the node."""
    if depth > 12:
        return "nesting too deep"
    if isinstance(v, dict):
        if _BYTES_TAG in v:
            h = v.get(_BYTES_TAG)
            if set(v) != {_BYTES_TAG} or not isinstance(h, str):
                return "malformed bytes tag"
            if len(h) > _BYTES_HEX_MAX:
                return f"bytes tag exceeds {_BYTES_HEX_MAX} hex characters"
            try:
                bytes.fromhex(h)
            except ValueError:
                return "bytes tag is not valid hex"
            return None
        return next((r for x in v.values() if (r := _bytes_tag_problem(x, depth + 1))), None)
    if isinstance(v, (list, tuple)):
        return next((r for x in v if (r := _bytes_tag_problem(x, depth + 1))), None)
    return None


def _external_seeds(seeds: Sequence[Any]) -> tuple[list, list[str]]:
    """Concrete inputs from other checkers (e.g. Z3 witnesses): objects with .args/.kwargs[/.source]
    or (args, kwargs[, source]) tuples. Values must be JSON-concrete; anything else is coverage loss."""
    ok, loss = [], []
    for i, sd in enumerate(seeds):
        if hasattr(sd, "args") or hasattr(sd, "kwargs"):
            a, k, src = getattr(sd, "args", []), getattr(sd, "kwargs", {}), getattr(sd, "source", "external")
        else:
            a, k, src = (*sd, "external")[:3]
        try:
            a, k = list(a or []), dict(k or {})
            json.dumps([a, k])
            bad_ = _bytes_tag_problem([a, k])
            if bad_:
                loss.append(f"seed {i} ({src}) not concretizable: {bad_}")
                continue
            ok.append((a, k, str(src)))
        except (TypeError, ValueError) as e:
            loss.append(f"seed {i} ({src}) not concretizable: {type(e).__name__}")
    return ok, loss


@dataclass(frozen=True)
class Seed:
    args: list
    kwargs: dict
    source: str


def seeds_from_z3(witness_inputs: Sequence[dict]) -> list[Seed]:
    """Concrete call inputs from hlith.z3_binding analysis['witness_inputs'].

    path_literals: {positional index | keyword: literal repr}. Keys listed in 'synthetic' are
    arbitrary placeholders (binding failure is value-independent): such a seed is labelled
    'z3-shape' so a witness never presents placeholder values as derived. With
    'includes_implicit_self' the indices count self/cls as written; the receiver slot is dropped,
    because the harness calls the function unbound. Missing values are None placeholders.
    """
    out = []
    for w in witness_inputs:
        lits = {}
        for key, text in (w.get("path_literals") or {}).items():
            try:
                lits[str(key)] = ast.literal_eval(text) if isinstance(text, str) else text
            except (ValueError, SyntaxError):
                pass
        synthetic = {str(x) for x in (w.get("synthetic") or [])}
        n = int(w.get("n_positional") or 0)
        start = 1 if w.get("includes_implicit_self") and n > 0 else 0
        idx = [str(i) for i in range(start, n)]
        args = [lits.get(i) for i in idx]
        kws = [kw if kw != "<any other keyword>" else "hlith_any_keyword" for kw in (w.get("keywords") or [])]
        kwargs = {kw: lits.get(kw) for kw in kws}
        keys = idx + kws
        complete = all(k in lits and k not in synthetic for k in keys)
        src = "z3" if complete else "z3-shape"
        out.append(Seed(args, kwargs, f"{src}:{w.get('kind', '?')}"))
    return out


def _validate_expr(param: str, expr: str) -> tuple[ast.AST | None, list[str]]:
    """Delegate predicate grammar validation to the shared capture/evaluator leaf."""
    try:
        return _delta_predicate_module().validate_expr(param, expr)
    except (ImportError, OSError, AttributeError):
        return None, ["expr predicate validator not supported (delta_predicate.py missing)"]


def _eval_expr(tree: ast.AST, param: str, value) -> bool:
    """Interpret a validated expr. Type errors while evaluating (e.g. len(None)) mean 'does not match'."""

    def ev(n):
        if isinstance(n, ast.Expression):
            return ev(n.body)
        if isinstance(n, ast.BoolOp):
            vals = (ev(v) for v in n.values)
            return all(vals) if isinstance(n.op, ast.And) else any(vals)
        if isinstance(n, ast.UnaryOp):
            return not ev(n.operand)
        if isinstance(n, ast.Compare):
            left = ev(n.left)
            for o, c in zip(n.ops, n.comparators):
                right = ev(c)
                ok = {ast.Eq: lambda a, b: a == b, ast.NotEq: lambda a, b: a != b, ast.Lt: lambda a, b: a < b,
                      ast.LtE: lambda a, b: a <= b, ast.Gt: lambda a, b: a > b, ast.GtE: lambda a, b: a >= b,
                      ast.In: lambda a, b: a in b, ast.NotIn: lambda a, b: a not in b,
                      ast.Is: lambda a, b: a is b, ast.IsNot: lambda a, b: a is not b}[type(o)](left, right)
                if not ok:
                    return False
                left = right
            return True
        if isinstance(n, ast.Name):
            return value
        if isinstance(n, ast.Constant):
            return n.value
        if isinstance(n, ast.Tuple):
            return tuple(ev(e) for e in n.elts)
        if isinstance(n, ast.Call):
            f = n.func
            if isinstance(f, ast.Name) and f.id == "len":
                return len(value)
            if isinstance(f, ast.Name) and f.id == "isinstance":
                t = _delta_predicate_module().EXPR_TYPES[n.args[1].id]
                return isinstance(value, t) and not (t is int and isinstance(value, bool))
            if f.attr in ("startswith", "endswith"):
                return getattr(value, f.attr)(ev(n.args[0]))
            return getattr(value, f.attr)()
        raise ValueError("unreachable: validated grammar")

    try:
        return bool(ev(tree))
    except (TypeError, AttributeError, ValueError):
        return False


def expr_matches(param: str, expr: str, value) -> bool:
    """PUBLIC, stable (Layer 5): does ``value`` (the declared parameter's value) satisfy a delta's expr
    predicate under the closed whitelist? An invalid expr never matches (fail closed)."""
    tree, errs = _validate_expr(param, expr)
    return False if errs else _eval_expr(tree, param, value)


DELTA_TYPED_CLASSES = ("empty_str", "none", "int_zero", "int_neg", "int_nonneg", "str_nonempty",
                       "empty_container", "mapping_key_absent", "bool")
_MAX_DELTA_INPUTS = 50


def _validate_deltas(deltas: Sequence[dict]) -> tuple[list[dict], list[str]]:
    """Declared intended deltas (proposer claims; runtime schema by review). Returns (checkable, errors).

    Only machine-checkable deltas can cover a divergence: predicate = literal_inputs (<= 50 concrete calls) or
    typed (one parameter, a closed narrow class) and expected = returns value_repr | raises exc_type. A broad or
    unknown predicate is an ERROR (fail closed), never silently widened. Deltas without a predicate are advisory:
    they are reported but cover nothing.
    """
    ok, errors = [], []
    for d in deltas or ():
        did = str(d.get("id", "?"))
        pred, exp = d.get("predicate"), d.get("expected")
        if pred is None:
            continue  # advisory text only
        if not isinstance(exp, dict) or exp.get("kind") not in ("returns", "raises", "returns_expr"):
            errors.append(f"delta {did}: predicate without a checkable expected outcome")
            continue
        if exp["kind"] == "returns_expr":
            try:
                validate_expected_expr = _expected_expr_module().validate_expected_expr
            except (ImportError, OSError, AttributeError):
                errors.append(f"delta {did}: returns_expr not supported (expected_expr.py missing)")
                continue
            ok_, why_ = validate_expected_expr(exp.get("expr") if isinstance(exp.get("expr"), str) else "", None)
            if not ok_:
                errors.append(f"delta {did}: expected expr rejected: {why_}")
                continue
            if pred is not None and isinstance(pred, dict) and pred.get("type") == "literal_inputs":
                errors.append(f"delta {did}: returns_expr needs a typed or expr predicate (one named parameter)")
                continue
        if exp["kind"] == "returns" and not isinstance(exp.get("value_repr"), str):
            errors.append(f"delta {did}: expected returns needs value_repr")
            continue
        if exp["kind"] == "raises" and not isinstance(exp.get("exc_type"), str):
            errors.append(f"delta {did}: expected raises needs exc_type")
            continue
        t = pred.get("type") if isinstance(pred, dict) else None
        if t == "literal_inputs":
            inputs = pred.get("inputs")
            if not isinstance(inputs, list) or not 1 <= len(inputs) <= _MAX_DELTA_INPUTS:
                errors.append(f"delta {did}: literal_inputs needs 1..{_MAX_DELTA_INPUTS} inputs")
                continue
            try:
                norm = [{"args": list(i.get("args") or []), "kwargs": dict(i.get("kwargs") or {})} for i in inputs]
                json.dumps(norm)
                if any(set(i) - {"args", "kwargs"} for i in inputs):
                    raise ValueError("only args/kwargs (env not allowed in V1)")
            except (TypeError, ValueError, AttributeError) as e:
                errors.append(f"delta {did}: literal inputs not concrete JSON: {e}")
                continue
            ok.append({"id": did, "symbol": d.get("symbol"), "type": t, "inputs": norm, "expected": exp})
        elif t == "typed":
            cls, param = pred.get("class"), pred.get("param")
            if cls not in DELTA_TYPED_CLASSES:
                errors.append(f"delta {did}: typed class {cls!r} not in the closed set {DELTA_TYPED_CLASSES}")
                continue
            if not isinstance(param, str) or not param.isidentifier():
                errors.append(f"delta {did}: typed predicate needs a parameter name")
                continue
            if cls == "mapping_key_absent" and not isinstance(pred.get("key"), str):
                errors.append(f"delta {did}: mapping_key_absent needs key")
                continue
            ok.append({"id": did, "symbol": d.get("symbol"), "type": t, "param": param, "class": cls,
                       "key": pred.get("key"), "expected": exp})
        elif t == "expr":
            if set(pred) != {"type", "param", "expr"}:
                errors.append(f"delta {did}: expr predicate takes exactly type/param/expr")
                continue
            _, xerrs = _validate_expr(pred.get("param"), pred.get("expr"))
            if xerrs:
                errors.append(f"delta {did}: " + "; ".join(xerrs))
                continue
            ok.append({"id": did, "symbol": d.get("symbol"), "type": t, "param": pred["param"], "expr": pred["expr"],
                       "expected": exp})
        else:
            errors.append(f"delta {did}: predicate type {t!r} rejected (only literal_inputs, typed or expr)")
    return ok, errors


_SYNTH_VERSION = "0.0.0+hlith.synthetic"


def _project_metadata(root: Path) -> tuple[str | None, str | None, str]:
    """(name, version, source) from the tree's own static metadata only: pyproject [project] / [tool.poetry],
    setup.cfg [metadata], or literal setup(name=..., version=...) kwargs. No code is executed. A dynamic or
    unresolvable version falls back to a marked synthetic version."""
    name = version = None
    src = "none"
    pp = root / "pyproject.toml"
    if pp.is_file():
        try:
            import tomllib

            data = tomllib.loads(pp.read_text(encoding="utf-8", errors="replace"))
            proj = data.get("project") or {}
            poetry = (data.get("tool") or {}).get("poetry") or {}
            name = proj.get("name") or poetry.get("name")
            if "version" not in (proj.get("dynamic") or []):
                version = proj.get("version") or poetry.get("version")
            src = "pyproject.toml" if name else src
        except (ValueError, OSError):
            pass
    cfg = root / "setup.cfg"
    if (not name or not version) and cfg.is_file():
        import configparser

        cp = configparser.ConfigParser(interpolation=None)
        try:
            cp.read_string(cfg.read_text(encoding="utf-8", errors="replace"))
            md = cp["metadata"] if cp.has_section("metadata") else {}
            name = name or md.get("name")
            v = md.get("version")
            if v and not v.strip().startswith(("attr:", "file:")):
                version = version or v.strip()
            src = "setup.cfg" if name and src == "none" else src
        except (configparser.Error, OSError):
            pass
    sp = root / "setup.py"
    if (not name or not version) and sp.is_file():
        tree = _parse(sp)
        for n in ast.walk(tree) if tree else ():
            if isinstance(n, ast.Call) and getattr(n.func, "id", getattr(n.func, "attr", None)) == "setup":
                for k in n.keywords:
                    ok, v = _literal(k.value) if k.arg in ("name", "version") else (False, None)
                    if ok and isinstance(v, str):
                        if k.arg == "name":
                            name = name or v
                        else:
                            version = version or v
                src = "setup.py" if name and src == "none" else src
    if name and not version:
        version = _SYNTH_VERSION
    return name, version, src


def _synthesize_dist_info(tree_root: Path, import_dir: Path, out_dir: Path) -> dict:
    """Read-only dist-info for a source tree: importlib.metadata.version(name) works in the evaluator without
    installing anything. Skipped when the import dir already carries metadata for that name."""
    name, version, src = _project_metadata(tree_root)
    if not name:
        return {"synthesized": False, "reason": "no static project name"}
    norm = re.sub(r"[-_.]+", "_", name).lower()
    for existing in list(import_dir.glob("*.dist-info")) + list(import_dir.glob("*.egg-info")):
        if existing.name.lower().startswith(norm + "-") or existing.name.lower() == norm + ".egg-info":
            return {"synthesized": False, "reason": f"tree already has {existing.name}"}
    d = out_dir / f"{norm}-{version}.dist-info"
    d.mkdir(parents=True, exist_ok=True)
    (d / "METADATA").write_text(f"Metadata-Version: 2.1\nName: {name}\nVersion: {version}\n")
    (d / "INSTALLER").write_text("case\n")
    return {"synthesized": True, "name": name, "version": version, "source": src, "dir": str(out_dir)}


_WITNESS_CAP = 256 * 1024
_EXTRA_BYTES = "protocol-extra-bytes"
