                    # exceptions) samples these directly; an unannotated or builtin-annotated one keeps its strategy
                    # and gets them as extra domain values (never narrowed)
                    ann_ = next((p_[1] for p_ in params if p_[0] == pn_), None)
                    head_ = (ann_ or "").replace(" ", "").split("[")[0].split("|")[0].split(".")[-1]
                    is_exc_ = isinstance(r_["value"], dict) and "__hlith_exc__" in r_["value"]
                    exc_ann_ = bool(ann_) and any(t_ in ann_ for t_ in ("Exception", "Error", "BaseException"))
                    re_ann_ = bool(ann_) and any(t_ in ann_ for t_ in ("Match", "Pattern"))
